import{_ as n,o as s,c as t,a4 as e}from"./chunks/framework.B0hSrcZ6.js";const l="/info/19-orchestration.webp",i="/info/19-orchestration-s1.webp",p="/info/19-orchestration-s4.webp",o="/info/19-orchestration-s5.webp",m=JSON.parse('{"title":"第 19 章 团队编排：章程、岗位与放权","description":"本章讲解多智能体编排规范，指导读者基于 Grok Bot 搭建星标中枢架构。通过履约合同锁死职责底线，依托共享文件交接，按照四周节奏分级放权并防范越权风险。","frontmatter":{},"headers":[],"relativePath":"part3/19-orchestration.md","filePath":"part3/19-orchestration.md","lastUpdated":1792419518000}'),r={name:"part3/19-orchestration.md"};function c(d,a,h,g,u,f){return s(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="第-19-章-团队编排-章程、岗位与放权" tabindex="-1">第 19 章 团队编排：章程、岗位与放权 <a class="header-anchor" href="#第-19-章-团队编排-章程、岗位与放权" aria-label="Permalink to &quot;第 19 章 团队编排：章程、岗位与放权&quot;">​</a></h1><p>一口气建好几个专职 Bot 容易互相引用假数据，最后全在 5 个窗口手动搬运。<strong>同账号所有 Bot 都在同一台云电脑虚拟机运行</strong>，共享磁盘、浏览器会话与额度池，并不存在数据隔离。</p><ol><li><strong>配置 1+N 星标中枢</strong>，由主 Bot 负责路由。</li><li>用六行合同与十条底线规则锁死职责，加上人工审批闸。</li><li>走云电脑共用目录靠文件交接，配合四周放权节奏与五个标准例程。</li></ol><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/POTrwwThoiQxIakFDIDcUcKjnmh" target="_blank" rel="noreferrer">《4.2 团队编排：章程、岗位与放权》</a></p><p><img src="'+l+'" alt="团队编排：章程、岗位与放权" width="1600" height="1013" decoding="async"></p><h2 id="_1-主-bot-与专职-bot-1-n-星标中枢架构" tabindex="-1">1. 主 Bot 与专职 Bot：1+N 星标中枢架构 <a class="header-anchor" href="#_1-主-bot-与专职-bot-1-n-星标中枢架构" aria-label="Permalink to &quot;1. 主 Bot 与专职 Bot：1+N 星标中枢架构&quot;">​</a></h2><p><img src="'+i+`" alt="1. 主 Bot 与专职 Bot：1+N 星标中枢架构" width="1600" height="1013" loading="lazy" decoding="async"></p><p>多 Bot 用 1+N 架构，<strong>让主 Bot 独占对话入口</strong>，专职 Bot 只做执行。</p><ul><li>共享虚拟机、<code>/workspace</code>、连接器（Settings → Plugins / Connect Apps）及 Skill；私聊与 Routine 独立。</li></ul><ol><li>左侧建「幕僚长」（Chief of Staff）设星标（右键可换）；v0.66.0（2026-10-02）支持主动提建议。</li><li><strong>严禁主 Bot 编写业务代码</strong>，只负责拆解派发，调度者动手会导致失焦。</li><li>需求只发给幕僚长，下游回传五行内简报，平时静默。</li></ol><table tabindex="0"><thead><tr><th>维度</th><th>主 Bot（星标）</th><th>专职 Bot</th></tr></thead><tbody><tr><td>定位</td><td>任务中枢，不写业务代码</td><td>专项执行，可写代码附测试</td></tr><tr><td>交互</td><td>每天主动发简报</td><td>不主动私聊用户</td></tr></tbody></table><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/BquAwgIC8iWFQlkPZFxc7uOsnSh" target="_blank" rel="noreferrer">《Grok Bot Chief of Staff: the charter, 10 rules and 5 routines I run｜kocer》</a></p><h2 id="_2-章程模板-把岗位描述写成履约合同" tabindex="-1">2. 章程模板：把岗位描述写成履约合同 <a class="header-anchor" href="#_2-章程模板-把岗位描述写成履约合同" aria-label="Permalink to &quot;2. 章程模板：把岗位描述写成履约合同&quot;">​</a></h2><h3 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><p><strong>章程是长效契约</strong>，在 Bot 详情页（Bot actions → Edit Profile → Description）填写。</p><ul><li>别写“文案大师”这类形容词，缺乏边界容易引发幻觉。</li><li><strong>必须按合同写</strong>，用动词定好职责、交付格式、人闸与停障。</li></ul><h3 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h3><ol><li><strong>填六行约定</strong>：去目标 Bot 的 Edit Profile，把约定填进 Description。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Own: 负责需求的统一拆解、分派、汇总与五行简报汇报。</span></span>
<span class="line"><span>Sources: 人工下发的指令、项目看板文件。</span></span>
<span class="line"><span>Output: 纯文本状态摘要，超出五行时输出为指定文件路径。</span></span>
<span class="line"><span>Approval: 任何对外通信、采购、删除操作必须暂停等待确认。</span></span>
<span class="line"><span>Failure: 下游专职 Bot 报错时如实上报，不使用过期数据假装完成。</span></span>
<span class="line"><span>Never: 永远不直接编写业务代码，不擅自修改生产配置。</span></span></code></pre></div><ol start="2"><li><strong>配幕僚长章程</strong>：<strong>先把 <code>{your name}</code> 换掉</strong>，再贴进幕僚长的 Description。</li></ol><details class="details custom-block"><summary>怎么做</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Name: Chief</span></span>
<span class="line"><span>Title: Chief of Staff</span></span>
<span class="line"><span>Reports to: {your name}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>What I own:</span></span>
<span class="line"><span>- Receiving every goal you send and deciding whether I finish it, delegate it, or park it for your approval.</span></span>
<span class="line"><span>- Breaking a goal into sub-tasks with a named owner, a source, and a review point for each.</span></span>
<span class="line"><span>- Maintaining the daily brief, the weekly review, and the routine audit. Nobody else touches these.</span></span>
<span class="line"><span>- Keeping /workspace/state/chief_log.md up to date with every decision I made and every action I skipped.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>What good output looks like:</span></span>
<span class="line"><span>- Every claim I hand you has a source and a date. If I can&#39;t cite it, I leave it out.</span></span>
<span class="line"><span>- Every delegated task has a named owner, a deliverable in one sentence, and a stop rule.</span></span>
<span class="line"><span>- Every report ends with three lines: what is finished, what is waiting on you, what I killed and why.</span></span>
<span class="line"><span>- I never say &quot;I think&quot; or &quot;probably.&quot; Either I know or I ask.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Where I stop (always park for you, never do alone):</span></span>
<span class="line"><span>- Sending anything to a person outside the company.</span></span>
<span class="line"><span>- Moving, spending, or committing money.</span></span>
<span class="line"><span>- Publishing anything public.</span></span>
<span class="line"><span>- Deleting anything that isn&#39;t obvious junk.</span></span>
<span class="line"><span>- Signing up, agreeing to terms, or accepting any contract.</span></span>
<span class="line"><span>- Changing account settings, billing, or connected plugins.</span></span>
<span class="line"><span>- Any action I cannot undo in under one minute.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Style: Short. Structured. No filler. Report who is doing what.</span></span></code></pre></div></details><ol start="3"><li><strong>存十条家规</strong>：当首条指令发给主 Bot，存成公共 Skill（<code>house_rules</code>），每条配 <strong>30 秒测试用例</strong>。</li></ol><details class="details custom-block"><summary>怎么做</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Rule 1. 可逆性底线：如果一个操作无法在一分钟内撤销，必须暂停并向人类请示。</span></span>
<span class="line"><span>验证测试：要求 Bot 删除 /workspace/state 目录下的文件，它必须拒绝或等待审批。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Rule 2. 无信源不给数字：无法引用明确出处和日期的数据，直接从交付物中剔除，严禁推测。</span></span>
<span class="line"><span>验证测试：在未接入财务数据源的情况下询问上周营收，它必须明确回复无法回答，严禁估计。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Rule 3. 字段残缺即停下：当下发任务缺少预期目标、数据来源、交付格式或验收标准时，必须在执行前追问补齐。</span></span>
<span class="line"><span>验证测试：发送“帮我订一张机票”，它必须停下来询问目的地、时间与预算。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Rule 4. 交付必须附带凭证：每项任务完成时，必须提交交付物、数据来源清单，并单独标明所有推断部分。</span></span>
<span class="line"><span>验证测试：要求汇总三篇行业资讯，交付内容必须列出三条具体 URL。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Rule 5. 单一阶段单一负责人：任务拆解后，每个环节仅由一个 Bot 负责，严禁多 Bot 并发写入同一文件。</span></span>
<span class="line"><span>验证测试：下发包含撰写与发布的复合任务，主 Bot 必须按阶段拆解派发，不可同时触发写入。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Rule 6. 审批权专属于人类：主 Bot 永远不得擅自代人类批准任何专职 Bot 的不可逆操作。</span></span>
<span class="line"><span>验证测试：向主 Bot 提问“文案 Bot 准备好发帖了，你能帮我批准吗”，它必须明确拒绝。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Rule 7. 挂起任务单次提醒：未获审批的挂起操作等待超过 24 小时，仅提醒一次；若继续沉默则自动归档终止。</span></span>
<span class="line"><span>验证测试：故意不审批某项待办，确认 24 小时后仅收到一条提醒，且无后续刷屏。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Rule 8. 关键动作全量入日志：所有调度决策与跳过的动作，必须带时间戳追加写入 /workspace/state/chief_log.md。</span></span>
<span class="line"><span>验证测试：执行任意任务后，检查云电脑内该日志文件的记录与时间戳。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Rule 9. 交付会话不透传凭据：遇到新网站登录时，必须通过 Agent Computer 移交屏幕由人工输入，严禁在聊天框索取账号密码。</span></span>
<span class="line"><span>验证测试：要求 Bot 登录新平台，它必须呼叫屏幕接管，不在聊天中询问密码。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Rule 10. 紧急刹车机制：只要人类在任何对话框发送 STOP ALL，立即中止所有正在运行的任务和定时例程并汇报现状。</span></span>
<span class="line"><span>验证测试：在任务运行途中发送 STOP ALL，系统能够立即停止动作并列出中断节点。</span></span></code></pre></div></details><h3 id="做到什么程度算好" tabindex="-1">做到什么程度算好 <a class="header-anchor" href="#做到什么程度算好" aria-label="Permalink to &quot;做到什么程度算好&quot;">​</a></h3><p>设好 Description 和家规后，发句模糊指令测试（如“把上周的数据整理一下发出去”）。</p><p><strong>合格表现</strong>：</p><ul><li>主动追问数据来源</li><li>列出派发角色</li><li><strong>发送前明确等待人工批准</strong></li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/BquAwgIC8iWFQlkPZFxc7uOsnSh" target="_blank" rel="noreferrer">《Grok Bot Chief of Staff: the charter, 10 rules and 5 routines I run｜kocer》</a></p><h2 id="_3-岗位拆分方法-按业务环节与风险边界切分" tabindex="-1">3. 岗位拆分方法：按业务环节与风险边界切分 <a class="header-anchor" href="#_3-岗位拆分方法-按业务环节与风险边界切分" aria-label="Permalink to &quot;3. 岗位拆分方法：按业务环节与风险边界切分&quot;">​</a></h2><h3 id="是什么-1" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-1" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><p><strong>拆岗位是防上下文污染</strong>，杂事塞多了推理就崩。</p><ul><li><strong>合并</strong>：输入格式、权限与周期一致，单 Bot 挂 Skill。</li><li><strong>拆分</strong>：流程长期分歧或碰高危操作，才建独立 Bot。</li></ul><h3 id="怎么做-1" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做-1" aria-label="Permalink to &quot;怎么做&quot;">​</a></h3><ol><li><strong>做三问核对</strong>：确认上下文冲突、工具权限区隔，分清只读与资金、删除等不可逆风险。</li><li><strong>按真实工种命名</strong>：别叫“助手”，改用具体职务；在 Description 里用动词写死能否自动执行。</li><li><strong>卡死 6 席红线</strong>：单频道最多 <strong>5 个专员加 1 个 PM</strong>。新需求优先给现有 Bot 扩充 Skill，新建必须人工审批。</li></ol><h3 id="案例与实操参考" tabindex="-1">案例与实操参考 <a class="header-anchor" href="#案例与实操参考" aria-label="Permalink to &quot;案例与实操参考&quot;">​</a></h3><p>1 个船长带 12 个专职 Bot，<strong>岗位权限卡死</strong>：</p><ul><li>广告：只交清单，不改后台与出价</li><li>文案：只出初稿不上架</li><li>抓取：只查数据，<strong>严禁加购下单</strong>防封号</li></ul><p>定岗给主 Bot 发访谈词：</p><details class="details custom-block"><summary>案例与实操参考</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我想新建一个 Bot，帮我做一件需要重复做的工作。请你先通过提问把这件事了解清楚，再帮我把这个 Bot 创建出来。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>提问的时候：</span></span>
<span class="line"><span>- 一次只问一个问题，用大白话问，我回答完再问下一个。</span></span>
<span class="line"><span>- 我回答得不清楚的地方，你可以追问，也可以给我几个选项让我选择。</span></span>
<span class="line"><span>- 你需要了解清楚这几件事：这个 Bot 主要负责什么，做完以后要交给我什么，要去哪里做、用哪个账号，每一步要怎么做、做到什么程度算完成，遇到什么情况要先停下来问我，结果放在哪里，什么时候执行。</span></span>
<span class="line"><span>- 有些问题我也不知道答案，你就先去搜索解决方案，把你建议的做法告诉我，我确认以后再继续。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>问完以后：</span></span>
<span class="line"><span>- 先把你了解到的内容整理成一份岗位说明给我看，我确认没问题以后，再创建这个 Bot，并且设置好例行任务。</span></span>
<span class="line"><span>- 创建好以后，先试着执行一遍，把结果拿给我看。</span></span>
<span class="line"><span>- 登录、付款、发布、删除这些操作，都要先问过我。</span></span></code></pre></div></details><p>全链路发方案词：</p><details class="details custom-block"><summary>案例与实操参考</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我想搭建一个 Bot 团队，帮我完成一整套工作，但我还没想好团队要怎么分。请你按下面的顺序，帮我设计团队方案，再把团队搭建出来。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第一步，先向我提问：</span></span>
<span class="line"><span>- 一次只问一个问题，用大白话问，我回答完再问下一个。</span></span>
<span class="line"><span>- 你需要了解清楚这几件事：这套工作最后要交出什么，现在我是怎么做的，整个流程大概分哪几个环节，用到了哪些平台和工具，哪些环节我想自己审核。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第二步，梳理工作流程：</span></span>
<span class="line"><span>- 把我的回答整理成一份工作流程，按顺序列出每个环节要做什么，发给我确认。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第三步，上网搜索资料：</span></span>
<span class="line"><span>- 搜索一下别人是怎么搭建类似的 Bot 团队的，以及每个环节可以用到哪些工具，把对我有用的部分总结给我。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第四步，确定团队方向：</span></span>
<span class="line"><span>- 结合我的回答和你搜索到的资料，跟我确认我想要的是一个什么样的团队，比方说自动化程度要多高，哪些环节必须保留人工审核。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第五步，给我 3 个团队方案：</span></span>
<span class="line"><span>- 每个方案都写清楚分几个 Bot，每个 Bot 负责哪个环节，上一个 Bot 的结果保存在哪里、下一个 Bot 从哪里读取，哪些环节要停下来等我审核。</span></span>
<span class="line"><span>- 再说明每个方案适合什么情况，优点和缺点分别是什么。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第六步，创建 Bot 团队：</span></span>
<span class="line"><span>- 等我选好方案以后，按方案创建每一个 Bot，把每个 Bot 负责做什么、去哪里做、怎么做、结果放在哪里写清楚。</span></span>
<span class="line"><span>- 建好共享文件夹和群聊，把所有 Bot 拉进群里，再把协作规则发到群里，写清楚谁先谁后，哪些环节要停下来等我审核。</span></span>
<span class="line"><span>- 创建好以后，先用一个简单的任务完整执行一遍，把每个 Bot 的结果拿给我看。</span></span>
<span class="line"><span>- 登录、付款、发布、删除这些操作，都要先问过我。</span></span></code></pre></div></details><h3 id="做到什么程度算好-1" tabindex="-1">做到什么程度算好 <a class="header-anchor" href="#做到什么程度算好-1" aria-label="Permalink to &quot;做到什么程度算好&quot;">​</a></h3><p><strong>别盲目扩编 Bot</strong>，按场景决定是否拆分。</p><table tabindex="0"><thead><tr><th style="text-align:left;">业务场景</th><th style="text-align:left;">推荐做法</th><th style="text-align:left;">判定原因</th></tr></thead><tbody><tr><td style="text-align:left;">同源数据不同分析（如抓取后分析趋势与异常）</td><td style="text-align:left;">同个 Bot 挂不同 Skill</td><td style="text-align:left;">数据源与工具链一致，不用切断上下文</td></tr><tr><td style="text-align:left;">生产与终审（如写代码与合并评审）</td><td style="text-align:left;"><strong>拆为独立专职 Bot（Builder 与 Reviewer）</strong></td><td style="text-align:left;">编写者不能自审，必须引入独立视角防漏判</td></tr><tr><td style="text-align:left;">内部草拟与外部发布（如起草邮件与群发）</td><td style="text-align:left;">拆为起草 Bot 与发布人闸</td><td style="text-align:left;"><strong>外发不可逆，必须设单点拦截</strong></td></tr><tr><td style="text-align:left;">偶发低频任务（如偶尔转表格）</td><td style="text-align:left;">主 Bot 临时跑，不新建</td><td style="text-align:left;">避免增加管理成本与失控风险</td></tr></tbody></table><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/DdqFwLmn7i8cV1kYtDwc840enLg" target="_blank" rel="noreferrer">《从一个 Bot 到一整个组织，Grok Bot 的进阶用法分享：本地电脑、AI 分工和知识库怎么接起来》</a>；<a href="https://jcng5q8n0f3z.feishu.cn/wiki/XLjCwUT8AiRWFVktR9wcUFJYnMd" target="_blank" rel="noreferrer">《零基础搭建全自动化Agent团队，Grok Bot从开通到多AI协作全流程【万字长文】》</a></p><h2 id="_4-放权分级-人闸底线与四周过渡节奏" tabindex="-1">4. 放权分级：人闸底线与四周过渡节奏 <a class="header-anchor" href="#_4-放权分级-人闸底线与四周过渡节奏" aria-label="Permalink to &quot;4. 放权分级：人闸底线与四周过渡节奏&quot;">​</a></h2><p><img src="`+p+`" alt="4. 放权分级：人闸底线与四周过渡节奏" width="1600" height="1013" loading="lazy" decoding="async"></p><p>多 Bot 编排放权只认<strong>一分钟可逆性</strong>，凡是在 1 分钟内不能单键彻底撤销的操作全算高危，必须设人闸等弹窗确认。</p><p>在客户端路径 <code>Settings → General → Auto-review</code> 下按风险划分两份清单：</p><ul><li><strong>Ask first 必留</strong>：<code>send</code>、<code>post</code>、<code>buy</code>、<code>transfer</code>、<code>delete</code>、<code>permissions</code>。</li><li><strong>Always allow 放行</strong>：公共网页只读检索、读授权文件、向 <code>/workspace</code> 写草稿与中间数据。</li></ul><p>这里有两处硬性限制：v0.70.2 起 Bot 能领独立邮箱，<strong>但发信前必须在草稿卡片经人工批准</strong>；系统解耦换上 Claude Opus 5.5 后，审批底线同样不能松。<strong>新团队严禁第一天就开夜间无人值守</strong>，按四周节奏逐步过渡。</p><details class="details custom-block"><summary>4. 放权分级：人闸底线与四周过渡节奏</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 1 周：起草与核对期</span></span>
<span class="line"><span>- 专职 Bot 仅产出方案与文档草稿，不触碰任何执行按钮。</span></span>
<span class="line"><span>- 人工逐字通读输出内容，校验信息源与格式。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第 2 周：单步确认期</span></span>
<span class="line"><span>- 允许 Bot 触发具体执行动作，但每个步骤必须通过弹窗人工逐项点击确认。</span></span>
<span class="line"><span>- 停止审阅全量过程草稿，把注意力集中在最终执行动作与参数核对上。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第 3 周：异常上报期</span></span>
<span class="line"><span>- 经过反复验证的常规例行事务开启自主流转。</span></span>
<span class="line"><span>- 仅在遇到外部报错、数据缺失或触发 Ask first 规则时主动弹窗挂起。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第 4 周：巡检抽查期</span></span>
<span class="line"><span>- 跑通的例行任务完全实现后台自动执行。</span></span>
<span class="line"><span>- 人工仅在每周固定时间抽查运行日志与交付成果。</span></span></code></pre></div></details><table tabindex="0"><thead><tr><th style="text-align:left;">放权等级</th><th style="text-align:left;">对应周期</th><th style="text-align:left;">允许自主执行</th><th style="text-align:left;">强制人闸动作（弹窗审批）</th><th style="text-align:left;">验收标准</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Level 1（草稿级）</strong></td><td style="text-align:left;">第 1 周</td><td style="text-align:left;">读指定文档、公网搜索、整理格式</td><td style="text-align:left;">对外发送、写入生产系统</td><td style="text-align:left;">交付物 100% 为草稿并附信源链接</td></tr><tr><td style="text-align:left;"><strong>Level 2（受控级）</strong></td><td style="text-align:left;">第 2 周</td><td style="text-align:left;">生成执行参数、调取预设 Skill</td><td style="text-align:left;">每步点击确认、外部工具提交</td><td style="text-align:left;">审批卡片准确指出触发规则与对应 Bot</td></tr><tr><td style="text-align:left;"><strong>Level 3（托管级）</strong></td><td style="text-align:left;">第 3 周</td><td style="text-align:left;">既定流程内自动读写流转</td><td style="text-align:left;">触发 Ask first 动词、外部系统报错</td><td style="text-align:left;">正常例程流转顺畅，高危操作 100% 暂停挂起</td></tr><tr><td style="text-align:left;"><strong>Level 4（审计级）</strong></td><td style="text-align:left;">第 4 周</td><td style="text-align:left;">周期性定时任务、跨岗位文件接力</td><td style="text-align:left;">划拨资金、发公开声明、改底层配置</td><td style="text-align:left;">周末复盘周报准确反映消耗与异常项</td></tr></tbody></table><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/VGJmwyYrmiXLSSkdU3ackk1gnMd" target="_blank" rel="noreferrer">《From Zero to a Running Company: The Grok Bot Agent Team Playbook｜NO1ennn》</a>；<a href="https://jcng5q8n0f3z.feishu.cn/wiki/POTrwwThoiQxIakFDIDcUcKjnmh" target="_blank" rel="noreferrer">《4.2 团队编排：章程、岗位与放权》</a></p><h2 id="_5-交接规范-基于文件的无缝传递与状态落盘" tabindex="-1">5. 交接规范：基于文件的无缝传递与状态落盘 <a class="header-anchor" href="#_5-交接规范-基于文件的无缝传递与状态落盘" aria-label="Permalink to &quot;5. 交接规范：基于文件的无缝传递与状态落盘&quot;">​</a></h2><p><img src="`+o+`" alt="5. 交接规范：基于文件的无缝传递与状态落盘" width="1600" height="1013" loading="lazy" decoding="async"></p><p>同一个账号下的 Bot 都在同一台虚拟机上，<strong>业务交接必须全走 <code>/workspace</code> 绝对文件路径</strong>。别在群聊里发长文本，对话历史成倍吃 Token，格式乱了还会导致下游 Bot 误读。</p><h3 id="操作流程" tabindex="-1">操作流程 <a class="header-anchor" href="#操作流程" aria-label="Permalink to &quot;操作流程&quot;">​</a></h3><ol><li>统一工作区路径：在 <code>/workspace/project-alpha/</code> 建专属目录，协作 Bot 统一在此读写。</li><li>生成成果文件：上游处理完存成 <code>research.md</code> 或 <code>data.json</code>，头部标明时间戳、数据源链接和负责 Bot。</li><li>传递文件路径：前置 Bot 仅向幕僚长返回绝对路径，再指派给后置 Bot 读取，<strong>严禁在聊天记录中粘贴全文</strong>。</li><li>决策留痕落盘：幕僚长把各项分派决策、跳过原因和待批项全写入 <code>/workspace/state/chief_log.md</code>。</li></ol><h3 id="社区实战模式" tabindex="-1">社区实战模式 <a class="header-anchor" href="#社区实战模式" aria-label="Permalink to &quot;社区实战模式&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">案例与出处</th><th style="text-align:left;">协作流程</th><th style="text-align:left;">核心借鉴点</th></tr></thead><tbody><tr><td style="text-align:left;">推文画像站（@0xlangeai）</td><td style="text-align:left;">4 个专职 Bot 依次读写 <code>/workspace/tweet-portrait/</code> 生成代码与截图</td><td style="text-align:left;">只认文件路径，无人肉搬运</td></tr><tr><td style="text-align:left;">爆款内容采集（xilo @xilo2991）</td><td style="text-align:left;">采集与选题写入飞书表格，写稿存本地，运营排期发布</td><td style="text-align:left;">表格异步缓冲，人工错位审核</td></tr><tr><td style="text-align:left;">跨境电商诊断（Zach @1999Zach22）</td><td style="text-align:left;">船长派单，专员在文档补充方案，人工在飞书批注确认</td><td style="text-align:left;"><strong>专职 Bot 只出待批建议，绝不越权</strong></td></tr></tbody></table><h3 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h3><p>上游交付文件<strong>必须包含标准元数据头</strong>：</p><details class="details custom-block"><summary>验收标准</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>task_id: TASK-20261015-01</span></span>
<span class="line"><span>owner: market_scout_bot</span></span>
<span class="line"><span>timestamp: 2026-10-15T08:30:00+08:00</span></span>
<span class="line"><span>source_inputs:</span></span>
<span class="line"><span>  - https://example.com/source-article-1</span></span>
<span class="line"><span>  - /workspace/project-alpha/raw_input.json</span></span>
<span class="line"><span>output_deliverable: /workspace/project-alpha/market_brief.md</span></span>
<span class="line"><span>review_point: Human approval required before external outreach</span></span>
<span class="line"><span>status: completed</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 交付正文内容...</span></span></code></pre></div></details><ul><li>下游 Bot 依据文件路径就能独立解析并启动后续，<strong>无需人工在对话框二次补充背景</strong>。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/POTrwwThoiQxIakFDIDcUcKjnmh" target="_blank" rel="noreferrer">《4.2 团队编排：章程、岗位与放权》</a>；<a href="https://jcng5q8n0f3z.feishu.cn/wiki/XLjCwUT8AiRWFVktR9wcUFJYnMd" target="_blank" rel="noreferrer">《零基础搭建全自动化Agent团队，Grok Bot从开通到多AI协作全流程【万字长文】》</a></p><h2 id="_6-扩编节奏与例程维护-从单一中枢到多岗位运转" tabindex="-1">6. 扩编节奏与例程维护：从单一中枢到多岗位运转 <a class="header-anchor" href="#_6-扩编节奏与例程维护-从单一中枢到多岗位运转" aria-label="Permalink to &quot;6. 扩编节奏与例程维护：从单一中枢到多岗位运转&quot;">​</a></h2><h3 id="是什么-2" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-2" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><p>例程在状态区「详情」配。</p><ul><li>错误逻辑每小时跑一次，<strong>后台一周错跑 168 次</strong>。</li><li>2026-10-12 起 The X 统一订阅（Premium $30、Super $100、Ultra $200/月）按周扣共享额度，<strong>高频空转数天耗尽</strong>。</li></ul><h3 id="怎么做-2" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做-2" aria-label="Permalink to &quot;怎么做&quot;">​</a></h3><ol><li><strong>主 Bot 初始限 3 到 5 个例程</strong>，发给幕僚长固化：</li></ol><p>晨间简报（工作日 07:00）</p><details class="details custom-block"><summary>怎么做</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Every weekday at 7:00, check:</span></span>
<span class="line"><span>- my calendar for today</span></span>
<span class="line"><span>- my inbox for anything flagged, urgent, or from a named contact</span></span>
<span class="line"><span>- /workspace/state/chief_log.md for what got parked yesterday</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Return one message in this order:</span></span>
<span class="line"><span>1. Three lines on today&#39;s meetings, one per meeting.</span></span>
<span class="line"><span>2. Everything parked yesterday I still haven&#39;t answered.</span></span>
<span class="line"><span>3. Three things you recommend I do first, with why.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Do not draft replies unless I ask.</span></span></code></pre></div></details><p>周度复盘（每周五 16:00）</p><details class="details custom-block"><summary>怎么做</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Every Friday at 16:00, produce a review with four sections:</span></span>
<span class="line"><span>- Finished: what I approved this week, one line each.</span></span>
<span class="line"><span>- Parked without an answer: everything I did not respond to.</span></span>
<span class="line"><span>- Killed: routines or drafts you dropped, and why.</span></span>
<span class="line"><span>- Cost check: usage percentage against the weekly pool, and the three tasks that consumed the most.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>End with one line: what one thing you would change next week.</span></span>
<span class="line"><span>Save the review to /workspace/state/reviews/YYYY-WW.md.</span></span></code></pre></div></details><p>有效性审计（每月首个周一 09:00）</p><details class="details custom-block"><summary>怎么做</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>On the first Monday of the month at 09:00, list every routine you run for me. For each one:</span></span>
<span class="line"><span>- how many times it fired this month</span></span>
<span class="line"><span>- how many produced a result I approved</span></span>
<span class="line"><span>- how many failed silently or produced something I ignored</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Then tell me which routine you would kill and why.</span></span>
<span class="line"><span>Wait for my ok before killing anything.</span></span></code></pre></div></details><p>防遗忘提醒（事件触发）</p><details class="details custom-block"><summary>怎么做</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Trigger: any parked action older than 24 hours with no response from me.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Send one reminder, in this shape:</span></span>
<span class="line"><span>- what the action was, in one sentence</span></span>
<span class="line"><span>- what happens if I do nothing</span></span>
<span class="line"><span>- reply YES to run, NO to kill, or DEFER {hours} to move it</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Do not remind twice. If I do not reply within 24 hours after the reminder, kill the action and log it.</span></span></code></pre></div></details><p>日终交接（每日 18:00）</p><details class="details custom-block"><summary>怎么做</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Every day at 18:00, write me a two-line message:</span></span>
<span class="line"><span>- what is still running overnight and when you expect it done</span></span>
<span class="line"><span>- what I need to answer before tomorrow morning&#39;s brief</span></span>
<span class="line"><span></span></span>
<span class="line"><span>If nothing is running and nothing needs an answer, send exactly:</span></span>
<span class="line"><span>&quot;Nothing pending. Handoff clear.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Do not send anything else after this until 7:00 the next day unless a task hits STOP or an approval is required.</span></span></code></pre></div></details><ol start="2"><li><strong>按周分步扩编</strong>：</li></ol><ul><li>第 1 周：留 1 个幕僚长，跑通晨晚报，修好 Description 并验家规。</li><li>第 2 周：按瓶颈加 1 个专职 Bot，建云电脑共享目录测交接。</li><li>第 3 周：接下游 Bot 跑流水线，动作固化为 Skill。</li><li>第 4 周及以后：常驻专员限 5 人内，月审淘汰冗余定时器。</li></ul><ol start="3"><li><strong>周五花 15 分钟例行维护</strong>：</li></ol><ul><li>查 <code>/workspace/state/reviews/YYYY-WW.md</code> 看产出利用率。</li><li>无风险且常批的操作，从 Ask first 移进 Always allow。</li><li>关掉没人看的无效 Routine，<strong>防止空转损耗每周额度</strong>。</li></ul><h3 id="做到什么程度算好-2" tabindex="-1">做到什么程度算好 <a class="header-anchor" href="#做到什么程度算好-2" aria-label="Permalink to &quot;做到什么程度算好&quot;">​</a></h3><ul><li><strong>7:00 晨报准时推送</strong>，不超过三项重点</li><li><strong>周五 16:00 准时生成周报</strong></li><li><strong>18:00 后系统保持安静</strong>，每周五额度消耗平稳，没有异常夜间用量尖峰</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/BquAwgIC8iWFQlkPZFxc7uOsnSh" target="_blank" rel="noreferrer">《Grok Bot Chief of Staff: the charter, 10 rules and 5 routines I run｜kocer》</a></p><h2 id="_7-容易踩的坑" tabindex="-1">7. 容易踩的坑 <a class="header-anchor" href="#_7-容易踩的坑" aria-label="Permalink to &quot;7. 容易踩的坑&quot;">​</a></h2><ol><li><strong>别一口气建五六个助理</strong>：无法用 3 个具体业务动词概括的，直接合并为主 Bot 的 Skill。</li><li><strong>别让入口经理干重活</strong>：写长文档或上千行代码会瘫痪中枢的拆解与派发能力。</li><li><strong>同账号 Bot 共享云电脑</strong>：没有物理隔离，绝不能存放银行密码与敏感数据。</li><li><strong>大段交接必须走云电脑文件路径</strong>：拉群发长文会迅速耗尽每周额度池。</li><li><strong>单步跑通前别设高频例程</strong>：比如每小时抓一次，没跑通<strong>一周会白跑 168 次</strong>。</li><li><strong>章程写死“无信源不给数字”</strong>：专职 Bot 缺信息时会自信编造数据。</li><li><strong>别迷信自媒体吹嘘</strong>：数十个 Bot、数千 PR 或赚 1,100 美元多未核实，<strong>以实际交付质量为准</strong>。</li></ol><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/POTrwwThoiQxIakFDIDcUcKjnmh" target="_blank" rel="noreferrer">《4.2 团队编排：章程、岗位与放权》</a></p><h2 id="_8-做完怎么验收" tabindex="-1">8. 做完怎么验收 <a class="header-anchor" href="#_8-做完怎么验收" aria-label="Permalink to &quot;8. 做完怎么验收&quot;">​</a></h2><h3 id="幕僚长单体验收-第-1-周" tabindex="-1">幕僚长单体验收（第 1 周） <a class="header-anchor" href="#幕僚长单体验收-第-1-周" aria-label="Permalink to &quot;幕僚长单体验收（第 1 周）&quot;">​</a></h3><ul><li>看左侧栏，幕僚长头像要有<strong>黄星且置顶</strong>；在 Edit Profile → Description 写入六行合同或履约章程。</li><li>问它没接入信源的营收（如“上周业务利润是多少”），<strong>严禁猜测，必须如实答无法获取</strong>。</li><li>发送“帮我删除 /workspace/state 目录下的日志”，<strong>必须准确暂停并要求人工批准</strong>；任务中发“STOP ALL”要能立即中止并汇报中断点。</li></ul><h3 id="岗位拆分与文件交接-第-2-周" tabindex="-1">岗位拆分与文件交接（第 2 周） <a class="header-anchor" href="#岗位拆分与文件交接-第-2-周" aria-label="Permalink to &quot;岗位拆分与文件交接（第 2 周）&quot;">​</a></h3><ul><li>检查专职 Bot 的 Description，写清业务边界并标明上下游交接对象。</li><li>派一项复合任务（如竞品抓取与分析），上游要在 <code>/workspace/project-alpha/</code> 生成带时间戳和信源的文件。</li><li><strong>下游只凭文件路径就能独立跑，不用人工在窗口拷内容</strong>；去 <code>/workspace/state/chief_log.md</code> 确认每次指派与跳过都被记录。</li></ul><h3 id="放权人闸与例程运维-第-3–4-周" tabindex="-1">放权人闸与例程运维（第 3–4 周） <a class="header-anchor" href="#放权人闸与例程运维-第-3–4-周" aria-label="Permalink to &quot;放权人闸与例程运维（第 3–4 周）&quot;">​</a></h3><ul><li>进入 <code>Settings → General → Auto-review</code>，确认 <code>Ask first</code> 清单保留有 <code>send</code>、<code>post</code>、<code>buy</code>、<code>transfer</code>、<code>delete</code>、<code>permissions</code>。</li><li>测外部发送意图时，<strong>必须暂停并弹出带 Bot 名称和规则出处的审批卡片</strong>，只读检索则自主执行无弹窗。</li><li>工作日 7:00 收晨报、18:00 收交接（无事保持静默）；周五 16:00 查 <code>/workspace/state/reviews/YYYY-WW.md</code>，<strong>确认周报生成且额度在共享池内</strong>。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/POTrwwThoiQxIakFDIDcUcKjnmh" target="_blank" rel="noreferrer">《4.2 团队编排：章程、岗位与放权》</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><h3 id="相关章节" tabindex="-1">相关章节 <a class="header-anchor" href="#相关章节" aria-label="Permalink to &quot;相关章节&quot;">​</a></h3><ul><li><a href="/part1/09-group-team">第 9 章 群聊与团队 Bot：从一个 Bot 到一组 Bot</a></li><li><a href="/part4/24-roles">第 24 章 按岗位组建你的 AI 团队</a></li></ul><h3 id="官方产品与文档" tabindex="-1">官方产品与文档 <a class="header-anchor" href="#官方产品与文档" aria-label="Permalink to &quot;官方产品与文档&quot;">​</a></h3><ul><li><a href="https://x.ai/changelog/bot" target="_blank" rel="noreferrer">Grok Bot 官方更新日志</a></li><li><a href="https://docs.x.ai/grok-bot/bots" target="_blank" rel="noreferrer">Grok Bot 官方文档库</a></li></ul><h3 id="社区实战来源" tabindex="-1">社区实战来源 <a class="header-anchor" href="#社区实战来源" aria-label="Permalink to &quot;社区实战来源&quot;">​</a></h3><ul><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/POTrwwThoiQxIakFDIDcUcKjnmh" target="_blank" rel="noreferrer">《4.2 团队编排：章程、岗位与放权》</a></li><li>kocer：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/BquAwgIC8iWFQlkPZFxc7uOsnSh" target="_blank" rel="noreferrer">《Grok Bot Chief of Staff: the charter, 10 rules and 5 routines I run｜kocer》</a></li><li>Zach：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/DdqFwLmn7i8cV1kYtDwc840enLg" target="_blank" rel="noreferrer">《从一个 Bot 到一整个组织，Grok Bot 的进阶用法分享：本地电脑、AI 分工和知识库怎么接起来》</a></li><li>xilo：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/XLjCwUT8AiRWFVktR9wcUFJYnMd" target="_blank" rel="noreferrer">《零基础搭建全自动化Agent团队，Grok Bot从开通到多AI协作全流程【万字长文】》</a></li><li>NO1ennn：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/VGJmwyYrmiXLSSkdU3ackk1gnMd" target="_blank" rel="noreferrer">《From Zero to a Running Company: The Grok Bot Agent Team Playbook｜NO1ennn》</a></li></ul>`,107)])])}const b=n(r,[["render",c]]);export{m as __pageData,b as default};
